import { k } from "./kaplayCtx";
import { loadGameEmojis } from "./utils/emoji";
import introScene from "./scenes/intro";
import gameScene from "./scenes/game";

// Registrar las escenas del juego
k.scene("intro", introScene);
k.scene("game", gameScene);

// Iniciar cargando todos los emojis de forma asíncrona
loadGameEmojis()
  .then(() => {
    // Una vez cargados, ir a la pantalla de bienvenida
    k.go("intro");
  })
  .catch((err) => {
    console.error("Error cargando los emojis del juego:", err);
  });
