let audioCtx: AudioContext | null = null;

/**
 * Genera y reproduce un sonido procedimental a partir de un arreglo de parámetros ZzFX.
 */
export function playZzFX(parameters: (number | undefined)[]): AudioBufferSourceNode | null {
  try {
    // Inicializar o reanudar el AudioContext ante la primera interacción
    if (!audioCtx) {
      const AudioCtxClass = window.AudioContext || (window as any).webkitAudioContext;
      audioCtx = new AudioCtxClass();
    }

    if (audioCtx.state === "suspended") {
      audioCtx.resume();
    }

    // Parámetros de ZzFX con valores por defecto
    const volume = parameters[0] ?? 0.3;
    const randomness = parameters[1] ?? 0.05;
    const frequency = parameters[2] ?? 220;
    const attack = parameters[3] ?? 0;
    const sustain = parameters[4] ?? 0;
    const decay = parameters[5] ?? 0.1;
    const shape = parameters[6] ?? 0; // 0: sin, 1: triangle, 2: saw, 3: square, 4: noise
    const shapeCurve = parameters[7] ?? 1;
    const slide = parameters[8] ?? 0;
    const deltaSlide = parameters[9] ?? 0;
    const pitchJump = parameters[10] ?? 0;
    const pitchJumpTime = parameters[11] ?? 0;
    const repeatTime = parameters[12] ?? 0;
    // const noise = parameters[13] ?? 0;
    const modulation = parameters[14] ?? 0;
    const bitCrush = parameters[15] ?? 0;
    const delay = parameters[16] ?? 0;
    const sustainVolume = parameters[17] ?? 1;
    // const decayStart = parameters[18] ?? 0;
    const sampleRate = 22050;

    // Calcular longitud de las secciones
    const attackSamples = sampleRate * attack;
    const sustainSamples = sampleRate * sustain;
    const decaySamples = sampleRate * decay;
    const delaySamples = sampleRate * delay;
    const totalSamples = attackSamples + sustainSamples + decaySamples + delaySamples;

    const bufferData: number[] = [];
    let currentFrequency = frequency;
    let radiansPerSample = (Math.PI * 2) / sampleRate;
    let phase = 0;
    let pitchJumpSamples = sampleRate * pitchJumpTime;
    let repeatSamples = sampleRate * repeatTime;
    let nextPitchJump = 0;
    let nextRepeat = 0;
    let modulationPhase = 0;

    for (let i = 0; i < totalSamples; ++i) {
      // Aplicar aleatoriedad
      if (randomness && Math.random() < randomness) {
        currentFrequency += (Math.random() * 2 - 1) * frequency * randomness;
      }

      // Envolvente de volumen (ADSR simplificado)
      let currentVolume = 0;
      if (i < attackSamples) {
        currentVolume = i / attackSamples;
      } else if (i < attackSamples + sustainSamples) {
        currentVolume = 1 - (1 - sustainVolume) * ((i - attackSamples) / sustainSamples);
      } else if (i < attackSamples + sustainSamples + decaySamples) {
        currentVolume = sustainVolume * (1 - (i - attackSamples - sustainSamples) / decaySamples);
      }

      // Fade out de retardo/eco final
      if (i >= totalSamples - delaySamples) {
        currentVolume *= (totalSamples - i) / delaySamples;
      }

      // Saltos de tono (Pitch Jumps)
      if (pitchJump && i >= nextPitchJump) {
        nextPitchJump = i + pitchJumpSamples;
        currentFrequency += pitchJump;
      }

      // Repetición
      if (repeatTime && i >= nextRepeat) {
        nextRepeat = i + repeatSamples;
        currentFrequency = frequency;
      }

      // Slide de tono progresivo
      currentFrequency += slide / sampleRate;
      currentFrequency += deltaSlide * Math.sin(i / sampleRate);

      // Vibrato / Modulación de tono
      if (modulation) {
        currentFrequency += Math.sin(modulationPhase) * modulation * currentFrequency;
        modulationPhase += radiansPerSample * 10; // Frecuencia de vibrato fija
      }

      // Calcular muestra de onda básica
      phase += (radiansPerSample * currentFrequency);
      let sample = 0;

      // Generar onda según la forma
      if (shape === 0) {
        sample = Math.sin(phase); // Senoidal
      } else if (shape === 1) {
        sample = Math.abs((phase % (Math.PI * 2)) / Math.PI - 1) * 2 - 1; // Triangular
      } else if (shape === 2) {
        sample = ((phase / Math.PI) % 2) - 1; // Diente de sierra
      } else if (shape === 3) {
        sample = Math.sin(phase) > 0 ? 1 : -1; // Cuadrada
      } else if (shape === 4) {
        sample = Math.random() * 2 - 1; // Ruido blanco
      }

      // Distorsión / BitCrush
      if (bitCrush) {
        sample = Math.round(sample * bitCrush) / bitCrush;
      }

      // Aplicar envolvente y volumen general
      let outputSample = sample * currentVolume * volume;

      // Forma de onda modificada/curvatura
      if (shapeCurve !== 1) {
        outputSample = outputSample < 0 
          ? -Math.pow(-outputSample, shapeCurve) 
          : Math.pow(outputSample, shapeCurve);
      }

      bufferData[i] = Math.max(-1, Math.min(1, outputSample));
    }

    // Crear buffer y reproducir
    const buffer = audioCtx.createBuffer(1, bufferData.length, sampleRate);
    buffer.getChannelData(0).set(bufferData);

    const source = audioCtx.createBufferSource();
    source.buffer = buffer;
    source.connect(audioCtx.destination);
    source.start();
    return source;
  } catch (e) {
    console.warn("ZzFX Error al reproducir audio:", e);
    return null;
  }
}

