import { playButtonSound } from "./sound";

let retryCallback: (() => void) | null = null;
let playAgainCallback: (() => void) | null = null;

// Inicializar selectores
const getElements = () => {
  const overlay = document.getElementById("overlay");
  const victoryPanel = document.getElementById("victory-panel");
  const defeatPanel = document.getElementById("defeat-panel");
  const giftPanel = document.getElementById("gift-panel");
  const teaserPanel = document.getElementById("teaser-panel");
  const specialGiftPanel = document.getElementById("special-gift-panel");

  const btnAcceptGift = document.getElementById("btn-accept-gift");
  const btnRetry = document.getElementById("btn-retry");
  const btnNextGift = document.getElementById("btn-next-gift");
  const btnRevealSpecial = document.getElementById("btn-reveal-special");
  const btnCloseSpecial = document.getElementById("btn-close-special");

  return { 
    overlay, 
    victoryPanel, 
    defeatPanel, 
    giftPanel, 
    teaserPanel, 
    specialGiftPanel, 
    btnAcceptGift, 
    btnRetry, 
    btnNextGift, 
    btnRevealSpecial, 
    btnCloseSpecial 
  };
};

// Configurar los manejadores de eventos DOM al cargar el script
document.addEventListener("DOMContentLoaded", () => {
  setupOverlayListeners();
});

// Por si acaso DOMContentLoaded ya se disparó
setTimeout(() => {
  setupOverlayListeners();
}, 100);

function setupOverlayListeners() {
  const els = getElements();

  if (els.btnAcceptGift) {
    // Evitar acumulamiento de listeners si se llama varias veces
    els.btnAcceptGift.replaceWith(els.btnAcceptGift.cloneNode(true));
    const newBtn = document.getElementById("btn-accept-gift");
    newBtn?.addEventListener("click", () => {
      playButtonSound();
      showGiftPanel();
    });
  }

  if (els.btnRetry) {
    els.btnRetry.replaceWith(els.btnRetry.cloneNode(true));
    const newBtn = document.getElementById("btn-retry");
    newBtn?.addEventListener("click", () => {
      playButtonSound();
      hideOverlay();
      if (retryCallback) retryCallback();
    });
  }

  if (els.btnNextGift) {
    els.btnNextGift.replaceWith(els.btnNextGift.cloneNode(true));
    const newBtn = document.getElementById("btn-next-gift");
    newBtn?.addEventListener("click", () => {
      playButtonSound();
      showTeaserPanel();
    });
  }

  if (els.btnRevealSpecial) {
    els.btnRevealSpecial.replaceWith(els.btnRevealSpecial.cloneNode(true));
    const newBtn = document.getElementById("btn-reveal-special");
    newBtn?.addEventListener("click", () => {
      playButtonSound();
      showSpecialGiftPanel();
    });
  }

  if (els.btnCloseSpecial) {
    els.btnCloseSpecial.replaceWith(els.btnCloseSpecial.cloneNode(true));
    const newBtn = document.getElementById("btn-close-special");
    newBtn?.addEventListener("click", () => {
      playButtonSound();
      hideOverlay();
      if (playAgainCallback) playAgainCallback();
    });
  }
}

function hideAllPanels(els: any) {
  els.victoryPanel?.classList.remove("active");
  els.defeatPanel?.classList.remove("active");
  els.giftPanel?.classList.remove("active");
  els.teaserPanel?.classList.remove("active");
  els.specialGiftPanel?.classList.remove("active");
}

export function showVictoryPanel() {
  setupOverlayListeners(); // Asegurar bindings
  const els = getElements();
  if (!els.overlay) return;

  hideAllPanels(els);
  els.overlay.classList.add("active");
  els.victoryPanel?.classList.add("active");
}

export function showDefeatPanel() {
  setupOverlayListeners();
  const els = getElements();
  if (!els.overlay) return;

  hideAllPanels(els);
  els.overlay.classList.add("active");
  els.defeatPanel?.classList.add("active");
}

export function showGiftPanel() {
  const els = getElements();
  if (!els.overlay) return;

  hideAllPanels(els);
  els.overlay.classList.add("active");
  els.giftPanel?.classList.add("active");
}

export function showTeaserPanel() {
  const els = getElements();
  if (!els.overlay) return;

  hideAllPanels(els);
  els.overlay.classList.add("active");
  els.teaserPanel?.classList.add("active");
}

export function showSpecialGiftPanel() {
  const els = getElements();
  if (!els.overlay) return;

  hideAllPanels(els);
  els.overlay.classList.add("active");
  els.specialGiftPanel?.classList.add("active");
}

export function hideOverlay() {
  const els = getElements();
  if (!els.overlay) return;

  els.overlay.classList.remove("active");
  hideAllPanels(els);
}

export function onRetry(callback: () => void) {
  retryCallback = callback;
}

export function onPlayAgain(callback: () => void) {
  playAgainCallback = callback;
}
