import { k } from "../kaplayCtx";
import { playStartSound } from "../utils/sound";

export default function introScene() {
  // 1. Fondo principal oscuro
  k.add([
    k.rect(k.width(), k.height()),
    k.color(11, 9, 20),
    k.z(-10),
  ]);

  // Patrón de rejilla de puntos decorativo en el fondo
  const dotSpacing = 40;
  for (let x = dotSpacing / 2; x < k.width(); x += dotSpacing) {
    for (let y = dotSpacing / 2; y < k.height(); y += dotSpacing) {
      k.add([
        k.circle(1.5),
        k.pos(x, y),
        k.color(30, 25, 50),
        k.opacity(0.3),
        k.z(-9),
      ]);
    }
  }

  // 2. Contenedor central (Glassmorphic Modal Panel adaptado a 450 de ancho)
  const panelWidth = 390;
  const panelHeight = 500;
  const centerY = k.height() / 2;

  // Sombra / Resplandor de fondo
  k.add([
    k.rect(panelWidth + 10, panelHeight + 10, { radius: 20 }),
    k.pos(k.width() / 2, centerY),
    k.anchor("center"),
    k.color(156, 39, 176), // Color morado/fiesta para el resplandor
    k.opacity(0.08),
    k.z(-2),
  ]);

  // Contenedor principal
  k.add([
    k.rect(panelWidth, panelHeight, { radius: 24 }),
    k.pos(k.width() / 2, centerY),
    k.anchor("center"),
    k.color(18, 15, 32),
    k.outline(2, k.rgb(45, 40, 75)),
    k.z(-1),
  ]);

  // 3. Títulos y Textos
  k.add([
    k.text("¡Feliz\nCumpleaños!\n🎂", {
      size: 32,
      font: "sans-serif",
      align: "center",
      lineSpacing: 10,
    }),
    k.pos(k.width() / 2, centerY - 140),
    k.anchor("center"),
    k.color(255, 215, 0), // Dorado festivo
  ]);

  k.add([
    k.text(
      "Aquí podrás descubrir tu regalo, pero primero tendrás que pasar una pequeña prueba.",
      {
        size: 16,
        font: "sans-serif",
        width: 320,
        align: "center",
        lineSpacing: 6,
      }
    ),
    k.pos(k.width() / 2, centerY),
    k.anchor("center"),
    k.color(180, 175, 210),
  ]);

  // 4. Emojis flotantes alrededor para dar ambiente festivo
  const spawnFloatingEmoji = (spriteName: string, x: number, y: number, phaseOffset: number) => {
    const emoji = k.add([
      k.sprite(spriteName),
      k.pos(x, y),
      k.anchor("center"),
      k.scale(0.7),
      k.rotate(0),
      k.z(1),
    ]);

    emoji.onUpdate(() => {
      emoji.pos.y = y + Math.sin(k.time() * 2 + phaseOffset) * 15;
      emoji.angle = Math.sin(k.time() * 1.5 + phaseOffset) * 8;
    });
  };

  // Colocar emojis festivos
  spawnFloatingEmoji("emoji-balloon", 60, centerY - 180, 0);
  spawnFloatingEmoji("emoji-gift", k.width() - 60, centerY - 180, Math.PI / 2);
  spawnFloatingEmoji("emoji-party", 70, centerY + 180, Math.PI);
  spawnFloatingEmoji("emoji-party-face", k.width() - 70, centerY + 180, Math.PI * 1.5);

  // 5. Botón de Jugar
  const btnWidth = 220;
  const btnHeight = 55;
  const btnY = centerY + 110;

  const btnBg = k.add([
    k.rect(btnWidth, btnHeight, { radius: 12 }),
    k.pos(k.width() / 2, btnY),
    k.anchor("center"),
    k.color(66, 133, 244), // Azul premium
    k.outline(2, k.rgb(120, 180, 255)),
    k.area(),
    k.scale(1),
  ]);

  k.add([
    k.text("¡JUGAR!", { size: 18, font: "sans-serif" }),
    k.pos(k.width() / 2, btnY),
    k.anchor("center"),
    k.color(255, 255, 255),
  ]);

  // Lógica interactiva del botón
  let isHovered = false;

  btnBg.onHoverUpdate(() => {
    isHovered = true;
    btnBg.color = k.rgb(85, 150, 255);
    k.setCursor("pointer");
  });

  btnBg.onHoverEnd(() => {
    isHovered = false;
    btnBg.color = k.rgb(66, 133, 244);
    k.setCursor("default");
  });

  btnBg.onUpdate(() => {
    const targetScale = isHovered ? 1.06 : 1.0;
    btnBg.scale = btnBg.scale.lerp(k.vec2(targetScale), k.dt() * 12);
  });

  btnBg.onClick(() => {
    playStartSound();
    
    // Pequeño efecto visual y cambio de escena
    k.tween(
      1.15,
      0.9,
      0.15,
      (v) => btnBg.scale = k.vec2(v),
      k.easings.easeOutQuad
    ).then(() => {
      k.go("game");
    });
  });
}
