import { k } from "../kaplayCtx";
import { 
  MAX_TURNS, 
  GRID_COLS, 
  GRID_ROWS, 
  TOTAL_PAIRS, 
  EMOJI_RENDER_SIZE, 
  GRID_PADDING, 
  TILE_GAP 
} from "../config";
import { 
  playFlipSound, 
  playMatchSound, 
  playMismatchSound, 
  playVictorySound, 
  playDefeatSound 
} from "../utils/sound";
import { 
  showVictoryPanel, 
  showDefeatPanel, 
  onRetry, 
  onPlayAgain, 
  hideOverlay 
} from "../utils/overlay";

export default function gameScene() {
  // Asegurar que el overlay empiece cerrado
  hideOverlay();

  // 1. Fondo principal oscuro
  k.add([
    k.rect(k.width(), k.height()),
    k.color(11, 9, 20),
    k.z(-10),
  ]);

  // Patrón de rejilla de puntos decorativo en el fondo
  const dotSpacing = 40;
  for (let x = dotSpacing / 2; x < k.width(); x += dotSpacing) {
    for (let y = dotSpacing / 2; y < k.height(); y += dotSpacing) {
      k.add([
        k.circle(1.5),
        k.pos(x, y),
        k.color(30, 25, 50),
        k.opacity(0.3),
        k.z(-9),
      ]);
    }
  }

  // 2. Estado del juego
  let firstSelected: any = null;
  let secondSelected: any = null;
  let state: "IDLE" | "WAITING" = "IDLE";
  let turnsLeft = MAX_TURNS;
  let pairsMatched = 0;

  // 3. HUD (Marcadores superiores)
  const hudTurns = k.add([
    k.text(`Fallos: 💙 ${turnsLeft}`, { size: 16, font: "sans-serif" }),
    k.pos(24, 45),
    k.color(180, 175, 210),
  ]);

  const hudPairs = k.add([
    k.text(`Parejas: ✨ ${pairsMatched}/${TOTAL_PAIRS}`, { size: 16, font: "sans-serif" }),
    k.pos(k.width() - 24, 45),
    k.anchor("topright"),
    k.color(180, 175, 210),
  ]);

  function updateHUD() {
    hudTurns.text = `Fallos: ${turnsLeft <= 10 ? "❤️" : "💙"} ${turnsLeft}`;
    hudPairs.text = `Parejas: ✨ ${pairsMatched}/${TOTAL_PAIRS}`;

    if (turnsLeft <= 10) {
      hudTurns.color = k.rgb(255, 80, 100);
    } else {
      hudTurns.color = k.rgb(180, 175, 210);
    }
  }

  // 4. Lógica de generación de la cuadrícula
  // Generar parejas según TOTAL_PAIRS
  const tileValues: number[] = [];
  for (let i = 0; i < TOTAL_PAIRS; i++) {
    tileValues.push(i);
    tileValues.push(i);
  }

  // Mezclar array (Fisher-Yates)
  for (let i = tileValues.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [tileValues[i], tileValues[j]] = [tileValues[j], tileValues[i]];
  }

  // Dimensiones de las losetas y posicionamiento dinámicos para llenar la pantalla
  const gap = TILE_GAP;
  const maxGridWidth = k.width() - GRID_PADDING * 2;
  const tileWidth = (maxGridWidth - (GRID_COLS - 1) * gap) / GRID_COLS;
  const tileHeight = tileWidth; // Hacerlas cuadradas
  
  // Calcular inicio del grid para centrarlo horizontal y verticalmente
  const gridWidth = GRID_COLS * tileWidth + (GRID_COLS - 1) * gap;
  const gridHeight = GRID_ROWS * tileHeight + (GRID_ROWS - 1) * gap;
  
  const startX = (k.width() - gridWidth) / 2 + tileWidth / 2;
  const startY = 140 + tileHeight / 2; // Margen superior del HUD

  // Contenedor visual del grid (opcional para estética premium)
  k.add([
    k.rect(gridWidth + 20, gridHeight + 20, { radius: 16 }),
    k.pos(k.width() / 2, startY - tileHeight / 2 + gridHeight / 2),
    k.anchor("center"),
    k.color(18, 15, 32),
    k.outline(2, k.rgb(35, 30, 60)),
    k.z(-2),
  ]);

  // Generar losetas en el canvas
  const tiles: any[] = [];

  for (let row = 0; row < GRID_ROWS; row++) {
    for (let col = 0; col < GRID_COLS; col++) {
      const idx = row * GRID_COLS + col;
      const val = tileValues[idx];
      
      const posX = startX + col * (tileWidth + gap);
      const posY = startY + row * (tileHeight + gap);

      // Loseta padre (posicionada en su centro)
      const tile = k.add([
        k.pos(posX, posY),
        k.anchor("center"),
        k.scale(1, 1),
        k.area({ shape: new k.Rect(k.vec2(0), tileWidth, tileHeight) }),
        "tile",
        {
          index: idx,
          value: val,
          isFlipped: false,
          isMatched: false,
          bgObj: null as any
        }
      ]);

      // Sprite de fondo de la loseta
      const bg = tile.add([
        k.rect(tileWidth, tileHeight, { radius: 8 }),
        k.anchor("center"),
        k.color(28, 24, 48),
        k.outline(2, k.rgb(60, 52, 96)),
      ]);
      tile.bgObj = bg;

      // Sprite del emoji (reverso por defecto) con escala dinámica proporcional
      const emojiScale = (tileWidth * 0.7) / EMOJI_RENDER_SIZE;
      tile.add([
        k.sprite("emoji-back"),
        k.anchor("center"),
        k.scale(emojiScale),
      ]);

      tiles.push(tile);

      // Hover visual
      tile.onHoverUpdate(() => {
        if (state === "WAITING" || tile.isFlipped || tile.isMatched) return;
        k.setCursor("pointer");
        bg.outline.width = 3;
        bg.outline.color = k.rgb(120, 100, 200);
      });

      tile.onHoverEnd(() => {
        k.setCursor("default");
        if (tile.isMatched) return; // Evitar sobreescribir el color verde de coincidencia
        bg.outline.width = 2;
        bg.outline.color = k.rgb(60, 52, 96);
      });

      // Clic
      tile.onClick(() => {
        if (state === "WAITING" || tile.isFlipped || tile.isMatched) return;

        // Voltear la primera/segunda
        state = "WAITING"; // Bloquear interacciones durante animación
        tile.isFlipped = true;
        bg.color = k.rgb(45, 38, 76); // Cambiar color de fondo del anverso
        bg.outline.color = k.rgb(100, 80, 180);

        playFlipSound();

        // Animar volteo (reverso -> anverso)
        flipTile(tile, `emoji-travel-${tile.value}`, () => {
          if (!firstSelected) {
            firstSelected = tile;
            state = "IDLE";
          } else {
            secondSelected = tile;

            // Comparar
            if (firstSelected.value === secondSelected.value) {
              // COINCIDENCIA!
              pairsMatched++;
              firstSelected.isMatched = true;
              secondSelected.isMatched = true;
              
              const t1 = firstSelected;
              const t2 = secondSelected;

              firstSelected = null;
              secondSelected = null;

              setTimeout(() => {
                playMatchSound();
                spawnMatchSparkles(t1.pos);
                spawnMatchSparkles(t2.pos);
                
                // Animar flash de coincidencia
                t1.bgObj.outline.color = k.rgb(100, 255, 100);
                t2.bgObj.outline.color = k.rgb(100, 255, 100);

                state = "IDLE";

                // Victoria
                if (pairsMatched === TOTAL_PAIRS) {
                  state = "WAITING";
                  setTimeout(() => {
                    playVictorySound();
                    showVictoryPanel();
                  }, 500);
                }
              }, 150);
            } else {
              // NO COINCIDEN!
              turnsLeft--;
              updateHUD();
              
              setTimeout(() => {
                playMismatchSound();
                
                const t1 = firstSelected;
                const t2 = secondSelected;

                firstSelected = null;
                secondSelected = null;

                // Voltear de vuelta a bocabajo
                flipTile(t1, "emoji-back");
                flipTile(t2, "emoji-back", () => {
                  t1.isFlipped = false;
                  t2.isFlipped = false;
                  
                  // Restaurar fondo original
                  t1.bgObj.color = k.rgb(28, 24, 48);
                  t1.bgObj.outline.color = k.rgb(60, 52, 96);
                  t2.bgObj.color = k.rgb(28, 24, 48);
                  t2.bgObj.outline.color = k.rgb(60, 52, 96);

                  state = "IDLE";

                  // Derrota
                  if (turnsLeft <= 0) {
                    state = "WAITING";
                    setTimeout(() => {
                      playDefeatSound();
                      showDefeatPanel();
                    }, 200);
                  }
                });
              }, 600);
            }
          }
        });
      });
    }
  }

  // 5. Animación de volteo usando scaleX
  function flipTile(tileObj: any, targetSprite: string, onComplete?: () => void) {
    k.tween(
      1,
      0,
      0.15,
      (val) => tileObj.scale.x = val,
      k.easings.easeInQuad
    ).then(() => {
      // Cambiar sprite
      const spriteObj = tileObj.children[1];
      if (spriteObj) {
        spriteObj.use(k.sprite(targetSprite));
      }

      k.tween(
        0,
        1,
        0.15,
        (val) => tileObj.scale.x = val,
        k.easings.easeOutQuad
      ).then(() => {
        if (onComplete) onComplete();
      });
    });
  }

  // 6. Efecto de partículas de chispas/estrellas
  function spawnMatchSparkles(pPos: any) {
    for (let i = 0; i < 8; i++) {
      const angle = (i / 8) * Math.PI * 2;
      const speed = k.rand(60, 110);
      const p = k.add([
        k.text("✨", { size: 14 }),
        k.pos(pPos.x, pPos.y),
        k.anchor("center"),
        k.opacity(0.9),
        k.z(5)
      ]);
      
      k.tween(pPos.x, pPos.x + Math.cos(angle) * speed * 0.4, 0.4, (val) => p.pos.x = val, k.easings.easeOutQuad);
      k.tween(pPos.y, pPos.y + Math.sin(angle) * speed * 0.4, 0.4, (val) => p.pos.y = val, k.easings.easeOutQuad);
      k.tween(0.9, 0, 0.4, (val) => p.opacity = val, k.easings.linear).then(() => p.destroy());
    }
  }

  // 7. Registrar Callbacks de overlays
  onRetry(() => {
    k.go("game");
  });

  onPlayAgain(() => {
    k.go("intro");
  });
}
