import { k } from "../kaplayCtx";
import { EMOJI_RENDER_SIZE } from "../config";

/**
 * Genera un sprite a partir de un emoji usando una fuente consistente.
 * Registra la carga en el ciclo de vida de KAPLAY de forma asíncrona.
 */
export function loadEmojiSprite(name: string, emoji: string, size = EMOJI_RENDER_SIZE) {
  const loadPromise = document.fonts.ready.then(() => {
    const canvas = document.createElement("canvas");
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext("2d");
    
    if (ctx) {
      // Activar suavizado en el canvas 2D
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = "high";
      
      ctx.font = `${size * 0.75}px "Noto Color Emoji", "Apple Color Emoji", "Segoe UI Emoji", sans-serif`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(emoji, size / 2, size / 2 + size * 0.06);
    }

    return new Promise<HTMLImageElement>((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = (err) => reject(err);
      img.src = canvas.toDataURL("image/png");
    });
  });

  return Promise.resolve(k.load(loadPromise.then((img) => {
    k.loadSprite(name, img);
  })));
}

/**
 * Carga todos los emojis necesarios para el juego: anversos de viajes, reverso y cumpleaños.
 */
export function loadGameEmojis() {
  const travelEmojis = [
    "✈️", "🚂", "🚢", "🏖️", "🗼", "🏔️", "🌴", "🧳",
    "🗺️", "🏕️", "🎒", "⛵", "🚁", "🏰", "🌋", "🐪",
    "🛶", "🚠", "🗿", "🎡", "🏝️", "📸", "🛳️", "🧭"
  ];

  const introEmojis = [
    { name: "cake", emoji: "🎂" },
    { name: "party", emoji: "🎉" },
    { name: "balloon", emoji: "🎈" },
    { name: "gift", emoji: "🎁" },
    { name: "party-face", emoji: "🥳" }
  ];

  const promises: Promise<any>[] = [];

  // Reverso
  promises.push(loadEmojiSprite("emoji-back", "🌍"));

  // Anversos de viajes (0 a 23)
  travelEmojis.forEach((emoji, index) => {
    promises.push(loadEmojiSprite(`emoji-travel-${index}`, emoji));
  });

  // Emojis de la pantalla de bienvenida
  introEmojis.forEach((item) => {
    promises.push(loadEmojiSprite(`emoji-${item.name}`, item.emoji));
  });

  return Promise.all(promises);
}
